import React, { useEffect, useState } from "react";



import { getStore, updStore, gen16CodeId,  fetchEncryptStream, ObjectKeys,  qryStore, parseFloatToDecimal, generateComprobanteId, getLabelTranslate } from "../../../stores/Utils";

import {  TextInput_Cmpt,  SvgIcon_Cmpt, CheckBoxSlide_Cmpt } from "../../../components";


import "./styles.css"
import { CloseModal } from "../../../components/DialogHRM";

import { useNavigate } from "react-router";
import { PickCustomer_Cmpt} from "../../ComprobanteParametrizados";

import ExtraCharges from "./ExtraCharges";
import { PickProduct_Cmpt, DateCalComponent_Cmpt } from "../../Inventory";
import { get_prod_stock } from "../../Inventory/services/server_fetching";

const Svg = SvgIcon_Cmpt();


const TextInput = TextInput_Cmpt();

const DateCalComponent =DateCalComponent_Cmpt();

const CheckBoxSlide = CheckBoxSlide_Cmpt();
const PickProvide = PickCustomer_Cmpt();
const PickProduct =PickProduct_Cmpt();


const frmNm = "new_fatura_sale_comprobante"






const MakeSaleFactura  = ({ data, confirm }) => {
	const [initialize, setInitialize] = useState(false);
	const [, set_obs] = useState(0);

	// const navigate = useNavigate();

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			updStore("accountPicker", {});
			set_obs(gen16CodeId())
		}
	});

	const updFrm = (f, v, k) => {
		let frm2 = getStore(frmNm) || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore(frmNm, frm2);
		
		set_obs(gen16CodeId())
	};



	let TotalAmount = getStore(frmNm)?.["isAdvance"] ? SumCollects(getStore("productListOnOut"),getStore("extraChargesInvoiceList")) :  getStore(frmNm)?.["totalAmount"] ;


	const save  = async ()  => {
		let ffm = getStore(frmNm);

		let date =   (new Date()).getTime()+800;
		if(ffm["date"]){
			let nn = (new Date(ffm["date"])).getTime();
			date = nn?nn:date;
		}
		ffm["date"] = date; 
		let comp2save = [];
		
		//let comprobanteId = await generateComprobanteId(ffm["date"]);
		//ffm["comprobanteId"] = comprobanteId;


		let hasAdvancePay = ffm["hasAdvancePay"];
		let hasTax = ffm["hasTax"];
		let isAdvance = ffm["isAdvance"];
		
		delete ffm["hasTax"];
		delete ffm["hasAdvancePay"];
		
	
		let totalC = 0;
		let sumInv = 0;
		let inventoryList = []


		let invoiceFrm = {...ffm};

		let clientName = ffm["clientName"]? " "+ffm["clientName"]: ""


		let dtAcc = getStore("global_account_params");

		if(isAdvance){
			let arr2 = getStore("productListOnOut") && ObjectKeys(getStore("productListOnOut"));
			arr2 && arr2?.map(async (element, indE)=>{
				
				let dataAcc = {...getStore("productListOnOut")[element]};
				
				let amount = (dataAcc["qty"]*1)*(dataAcc["price"]*1);
				
				totalC +=  amount;
				sumInv +=  amount;

				inventoryList.push({
					inventoryId: gen16CodeId(),
					product: dataAcc["productId"],
					qty: dataAcc["qty"]*1,
					salePrice: dataAcc["salePrice"]*1,
					price: dataAcc["price"]*1,
					amount:amount
				})
			});

		
			if(sumInv > 0){
				let nnfrm3 = {...ffm};
				nnfrm3["type"] =  "credit";
				nnfrm3["account"] = dtAcc?.inventory?.account;
				nnfrm3["amount"] =  sumInv;
				nnfrm3["operationId"] = gen16CodeId();
				comp2save.push(nnfrm3)


				let nnfrm4 = {...ffm};
				nnfrm4["type"] =  "debit";
				nnfrm4["account"] = dtAcc?.inventory_expensess?.account;
				nnfrm4["amount"] =  sumInv;
				nnfrm4["operationId"] = gen16CodeId();
				comp2save.push(nnfrm4)
				
			}


			if(totalC > 0 && getStore("customerOutPicker").account ){
				let nnfrm3 = {...ffm};
				nnfrm3["type"] =  "debit";
				nnfrm3["account"] =  getStore("customerOutPicker")?.["account"];
				nnfrm3["subAccount"] =  getStore("customerOutPicker")?.["subAccount"];
				nnfrm3["providerId"] =  getStore("customerOutPicker")?.["providerId"];
				nnfrm3["operationId"] = gen16CodeId();
				let accountDeb = getStore("account_ids")?.[getStore("customerOutPicker")?.["account"]];
				if(accountDeb && accountDeb.payOrCollect){
					nnfrm3["payOrCollect"] = accountDeb.payOrCollect;
				}
				nnfrm3["amount"] =   hasTax ?( hasTax /100 *  TotalAmount) + TotalAmount*1: TotalAmount*1;
				comp2save.push(nnfrm3)
			}

			if(hasTax){
				let nnfrm6 = {...ffm};
				nnfrm6["type"] =  "credit";
				nnfrm6["account"] = dtAcc?.sale_tax?.account;
				nnfrm6["operationId"] = gen16CodeId();
				nnfrm6["amount"] =  TotalAmount*hasTax/100;
				comp2save.push(nnfrm6)
			}

			if(dtAcc?.sales_income?.account){
				let nnfrm6 = {...ffm};
				nnfrm6["type"] =  "credit";
				nnfrm6["account"] = dtAcc?.sales_income?.account;
				nnfrm6["operationId"] = gen16CodeId();
				nnfrm6["amount"] =TotalAmount;
				comp2save.push(nnfrm6)
			}

			if(hasAdvancePay){
				invoiceFrm["hasAdvancePay"] = hasAdvancePay*1;
			}

			if(hasTax){
				invoiceFrm["hasTax"] = hasTax /100 *  TotalAmount;
			}
	
			invoiceFrm["extras"] = getStore("extraChargesInvoiceList");
		}
		else{
			TotalAmount = ffm["totalAmount"];
			let pvd = getStore("providers_ids")[getStore("customerOutPicker")?.["providerId"]]?.name;
			
			if(pvd){
				invoiceFrm["description"] = `${pvd} - ${clientName}`;
			}
		}


		

		invoiceFrm["invoiceId"] = gen16CodeId();
		invoiceFrm["products"] =  inventoryList;
		invoiceFrm["amount"] = TotalAmount*1;
		invoiceFrm["createdBy"] = getStore("profileUser")?.userId;
		invoiceFrm["customer"] =  {
			account: getStore("customerOutPicker")?.["account"],
			subAccount:  getStore("customerOutPicker")?.["subAccount"],
			providerId: getStore("customerOutPicker")?.["providerId"]
		}
	
		invoiceFrm["comprobantes"] = comp2save;
		
		

		let bdyqInvoice = {...getStore(qryStore())?.add_invoice};
		bdyqInvoice.params = {
			businessId:  getStore("profileUser")?.businessId,
			year: getStore("date_current_year")
		}
		bdyqInvoice.form=invoiceFrm;

		const a2S = true;
		

		// console.log(bdyqInvoice)
		
		if(a2S){
			const res = fetchEncryptStream(bdyqInvoice);
			const td = await res;
			// console.log(td)
			if (td) {
				//Log$$(td)
			}
			data?.modalID && CloseModal({id:data?.modalID});
		
			setTimeout(() => {
				updStore("extraChargesInvoiceList", null);
				updStore("productListOnOut", null);
				updStore("customerOutPicker", null);
				updStore(frmNm, null)
				set_obs(gen16CodeId());
				confirm && confirm();
				
			}, 400);
		}
		
		
		
			
		
	};

	
	
	
	
	
	


	return (
		<div style={{
			maxHeight: "90vh",
			minHeight:  "58vh",
			width: "860px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title">
				{getLabelTranslate(1)}
				</p>
				
				<div className="flexSpace"/>
				<div className="_dsplFlx " style={{marginTop: 20}}>
					<CheckBoxSlide
						initvalue={getStore(frmNm)?.["isAdvance"]}
						keyCode={57}
						updChange={(e)=>updFrm("isAdvance",e)}
					/>
					<span className={`checklabel`}>
						{"Avanzado"}
					</span>
				</div>
			</div>

			<div className="_dsplFlx ">
				<DateCalComponent 
					label={getLabelTranslate(3)}
					init={getStore(frmNm)?.["date"]} 
					updDate={(e)=>updFrm("date",e)} 
				/>
               

				<div className="flexSpace"/>
				<TextInput  
					init={getStore(frmNm)?.["document"]} 
					label={getLabelTranslate(2)} 
					width={120} 
					updChanges={(e)=>updFrm("document",e)}
				/>
				<div className="flexSpace"/>
				{getStore(frmNm)?.["isAdvance"]? 
				<TextInput  
					init={getStore(frmNm)?.["hasTax"]} 
					label={getLabelTranslate(16)} 
					width={120} 
					updChanges={(e)=>updFrm("hasTax",e)}
				/>
				:null}
				<div className="flexSpace"/>
				{getStore(frmNm)?.["isAdvance"]? 
				<div>
					<p className="label">
						{ "Total"}
					</p>
					<div className="date2Upd" style={{marginRight:30}} >
						{(TotalAmount?TotalAmount:0).toFixed(2)}
					</div>
				</div>
				:
				<TextInput   
					init={getStore(frmNm)?.["totalAmount"]} 
					label={"Monto"} 
					width={120} 
					type={"number"}
					updChanges={(e)=>updFrm("totalAmount",e)}
				/>
				}
			</div>

			
			{getStore(frmNm)?.["isAdvance"]? 
			<>
				<div className="_dsplFlx "  style={{margin: "18px 10px"}}>
					<ProviderBox />
					<div className="flexSpace"/>
					<TextInput  
						init={getStore(frmNm)?.["hasAdvancePay"]} 
						label={getLabelTranslate(15)} 
						width={120} 
						updChanges={(e)=>updFrm("hasAdvancePay",e)}
					/>
				</div>
				<div className="_dsplFlx "  style={{margin: "18px 0"}}>
					<div className="flexSpace"/>
					<TextInput  
						init={getStore(frmNm)?.["description"]} 
						label={getLabelTranslate(4)} 
						width={520} 
						updChanges={(e)=>updFrm("description",e)}
					/>
					<div className="flexSpace"/>
				</div>
				
				
				<ProductsBox updMain={set_obs} />

				<ExtraCharges updMain={set_obs} />

			</>:
				<div>
					<div className="_dsplFlx "  style={{margin: "18px 10px"}}>
						<div className="flexSpace"/>
						<ProviderBox />
						<div className="flexSpace"/>
						
					</div>
					<div className="_dsplFlx "  style={{margin: "18px 10px"}}>
						
						<div className="flexSpace"/>
						<TextInput  
							init={getStore(frmNm)?.["clientName"]} 
							label={"Nombe del cliente"} 
							width={420} 
							updChanges={(e)=>updFrm("clientName",e)}
						/>
						<div className="flexSpace"/>
					</div>
				</div>
			}
			<div className="_dsplFlx ">
				<div className="flexSpace"/>
				{getStore(frmNm)?.["document"] &&   getStore("customerOutPicker")?.account && TotalAmount>0?
				<div className="card">
					<button onClick={save}>
						{getLabelTranslate(5)}
					</button>
				</div>
				:null}
			</div>
		

			
		</div>
	);
};

export default MakeSaleFactura;





const EstaCuadrado = (obj) => {
	let balance = 0;
	let arr = obj && ObjectKeys(obj);
	arr && arr?.map((element, indE)=>{
		let data = obj[element];
		let newB = balance.toFixed(2);
		let amount = data?.amount ? data?.type === "debit" ?  parseFloat(data.amount) :parseFloat(data.amount) *-1  : 0;
		balance = amount + parseFloat(newB);
		
	});
	return arr && arr?.length>0 && balance === 0;
}  



const ProviderBox = ({}) => {
	const [obs, set_obs] = useState(0);


	
	const  handlePick = (v) =>{
		let nn= {
			"providerId":v.providerId,
			"account":v.account,
			"subAccount":v.subAccount,
		}
		updStore("customerOutPicker", nn);
		set_obs(gen16CodeId())
	}

	const  clear = () =>{
		updStore("customerOutPicker", null);
		set_obs(gen16CodeId())
	}

	let accountD = getStore("providers_ids")?.[getStore("customerOutPicker")?.providerId];
	

	return (
		<div >
				{accountD?.name ? 
				<div className="_dsplFlx " style={{margin: "18px 0"}}>
					<div className=" acc_dtls">
						<div className="_dsplFlx"  >
							<div className="code" style={{color: "#646cff"}} onClick={clear}>
								{accountD?.name} 
							</div>
						</div>
						<div className="flexSpace"/>
					</div>
					
				</div> :
				<PickProvide
					placeholder={"buscar una provedor"} 
					width={320}
					handleClick={handlePick}
				/>
				}
			</div>

	)
}











